begin;set local search_path=public,extensions,pg_temp;create extension if not exists pgtap with schema extensions;select no_plan();
select ok(not has_function_privilege('anon','public.delete_education_video(uuid,uuid,integer)','execute'),'Anonymous deletion denied');
select ok(has_function_privilege('authenticated','public.delete_education_video(uuid,uuid,integer)','execute'),'Owned deletion RPC is available');
create temporary table baseline as select used_bytes,retained_outputs from public.usage_accounts where scope='global';
