values('a2500000-0000-4000-8000-000000000041','a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000001','a2500000-0000-4000-8000-000000000031',1,'audio','audio','artifacts','a2500000-0000-4000-8000-000000000001/a2500000-0000-4000-8000-000000000011/a2500000-0000-4000-8000-000000000041/fixture.wav','available',10,10,repeat('c',64),'audio/wav','audio/wav',now()-interval '2 days',now()-interval '2 days',now()+interval '5 days',now()-interval '2 days');
insert into public.usage_ledger(operation_key,owner_id,asset_id,used_bytes_delta,reserved_bytes_delta,retained_outputs_delta,reserved_outputs_delta,reason) values('artifact:a2500000-0000-4000-8000-000000000041','a2500000-0000-4000-8000-000000000001','a2500000-0000-4000-8000-000000000041',10,0,0,0,'synthetic charge');
insert into public.revision_assets(revision_id,asset_id,project_id,owner_id,purpose,retain_until) values('a2500000-0000-4000-8000-000000000021','a2500000-0000-4000-8000-000000000041','a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000001','intermediate',now()+interval '5 days');
