select set_config('request.jwt.claims','{"sub":"a2500000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.delete_education_video('a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000021',1)$$,'42501',null::text,'Foreign deletion denied');
select set_config('request.jwt.claims','{"sub":"a2500000-0000-4000-8000-000000000001","role":"authenticated"}',true);
