select throws_ok($$select public.delete_education_video('a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000022',2)$$,'P2404',null::text,'Unfinished revisions are not deletable results');
select is(public.delete_education_video('a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000021',1)->>'cleanupState','pending','Explicit deletion schedules future-retained artifacts safely');
