select is(public.delete_education_video('a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000021',1)->>'deleted','true','Lost-response replay is idempotent');
select is((select count(*)::integer from public.usage_ledger where operation_key='video:delete:a2500000-0000-4000-8000-000000000021'),1,'Only one slot debit is recorded');
select ok(private.media_cleanup_eligible('a2500000-0000-4000-8000-000000000041',now()),'Deleted producer can clean its own future-retained artifact');
insert into public.revision_assets(revision_id,asset_id,project_id,owner_id,purpose,retain_until) values('a2500000-0000-4000-8000-000000000022','a2500000-0000-4000-8000-000000000041','a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000001','intermediate',now()+interval '5 days');
