select ok(not private.media_cleanup_eligible('a2500000-0000-4000-8000-000000000041',now()),'Late upload safety window is retained');
update public.jobs set finished_at=now()-interval '2 days' where id='a2500000-0000-4000-8000-000000000031';
select set_config('request.jwt.claims','{}',true);
select throws_ok($$select public.get_video_deletion('a2500000-0000-4000-8000-000000000011','a2500000-0000-4000-8000-000000000021')$$,'42501',null::text,'Missing identity cannot read deletion receipts');
set constraints all immediate;select * from finish();rollback;
